-- SCH-1 group 4 — lodging.
--   * room_types.name_i18n / description_i18n (JSONB {locale: text}); name / description stay
--     as the default-locale fallback.
--   * rooms: partial UNIQUE (tenant_id, property_id, number) WHERE deleted_at IS NULL replaces
--     the "<id8>~deleted" rename hack (a deleted room frees its number).
--   * rates.max_stay, closed_to_arrival, closed_to_departure (per season / day mask).
-- Section 1 is generated by Prisma; sections 2+ are hand-written.

-- ─────────────────────────── 1. DDL (prisma migrate diff) ───────────────────────────
-- DropIndex
DROP INDEX "rooms_tenant_id_property_id_number_key";

-- AlterTable
ALTER TABLE "rates" ADD COLUMN     "closed_to_arrival" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "closed_to_departure" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "max_stay" INTEGER;

-- AlterTable
ALTER TABLE "room_types" ADD COLUMN     "description_i18n" JSONB,
ADD COLUMN     "name_i18n" JSONB NOT NULL DEFAULT '{}';

-- ─────────────────────────── 2. Data migration ───────────────────────────
-- 2.1 Translations: the current label in the tenant default locale (French by default).
UPDATE "room_types" rt SET
  name_i18n = jsonb_build_object(COALESCE(t.default_locale, 'fr'), rt.name),
  description_i18n = CASE WHEN rt.description IS NULL THEN NULL
                          ELSE jsonb_build_object(COALESCE(t.default_locale, 'fr'), rt.description) END
  FROM "tenants" t
 WHERE t.id = rt.tenant_id;

-- 2.2 Deleted rooms renamed "<id8>~deleted": restore the number printed on their latest police
-- record (snapshot.roomNumber) when there is one; the others keep the placeholder.
UPDATE "rooms" r SET number = src.number
  FROM (
    SELECT DISTINCT ON (rr.room_id) rr.room_id, pr.snapshot->>'roomNumber' AS number
      FROM "police_records" pr
      JOIN "stays" s ON s.id = pr.stay_id
      JOIN "reservation_rooms" rr ON rr.id = s.reservation_room_id
     WHERE rr.room_id IS NOT NULL AND COALESCE(pr.snapshot->>'roomNumber', '') <> ''
     ORDER BY rr.room_id, pr.created_at DESC) src
 WHERE r.id = src.room_id AND r.deleted_at IS NOT NULL AND r.number LIKE '%~deleted';

-- ─────────────────────────── 3. Integrity ───────────────────────────
CREATE UNIQUE INDEX rooms_number_active_key ON "rooms" (tenant_id, property_id, number)
  WHERE deleted_at IS NULL;

ALTER TABLE "room_types" ADD CONSTRAINT room_types_name_i18n_check CHECK (jsonb_typeof(name_i18n) = 'object');
ALTER TABLE "room_types" ADD CONSTRAINT room_types_description_i18n_check
  CHECK (description_i18n IS NULL OR jsonb_typeof(description_i18n) = 'object');
ALTER TABLE "rates" ADD CONSTRAINT rates_stay_check
  CHECK (min_stay >= 1 AND (max_stay IS NULL OR max_stay >= min_stay));
